DROP TABLE IF EXISTS credentials, disputes, payouts, escrows, reviews, contributions, milestones, charter_acceptances, charters, project_members, ledger_entries, projects, users CASCADE;
CREATE TABLE users(id SERIAL PRIMARY KEY,name TEXT,email TEXT UNIQUE,password_hash TEXT,role TEXT,verification_status TEXT DEFAULT 'pending',skills TEXT[] DEFAULT '{}',availability TEXT,coi_sponsor_id INT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE projects(id SERIAL PRIMARY KEY,sponsor_id INT REFERENCES users(id),title TEXT,public_summary TEXT,confidential_brief TEXT,status TEXT DEFAULT 'draft',engagement_model TEXT,budget INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE project_members(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id),user_id INT REFERENCES users(id),role TEXT,status TEXT DEFAULT 'invited',joined_at TIMESTAMPTZ DEFAULT now(),UNIQUE(project_id,user_id));
CREATE TABLE charters(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id),version INT,engagement_model TEXT,scope TEXT,rewards TEXT,ip_rules TEXT,publication_rules TEXT,confidentiality_rules TEXT,ai_rules TEXT,credit_split TEXT,exit_rules TEXT,dispute_rules TEXT,commercialization_rules TEXT,status TEXT DEFAULT 'published',created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(project_id,version));
CREATE TABLE charter_acceptances(id SERIAL PRIMARY KEY,charter_id INT REFERENCES charters(id),user_id INT REFERENCES users(id),accepted_at TIMESTAMPTZ DEFAULT now(),UNIQUE(charter_id,user_id));
CREATE TABLE milestones(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id),title TEXT,description TEXT,required_skills TEXT[],deliverable TEXT,acceptance_criteria TEXT,amount INT DEFAULT 0,status TEXT DEFAULT 'PLANNED');
CREATE TABLE contributions(id SERIAL PRIMARY KEY,project_id INT,milestone_id INT,user_id INT,artifact TEXT,artifact_hash TEXT,description TEXT,ai_declared BOOLEAN DEFAULT false,similarity INT,impact_score NUMERIC,quality_score NUMERIC,reviewed_effort NUMERIC,status TEXT DEFAULT 'SUBMITTED',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE reviews(id SERIAL PRIMARY KEY,contribution_id INT,reviewer_id INT,quality NUMERIC,impact NUMERIC,decision TEXT,comments TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE escrows(id SERIAL PRIMARY KEY,project_id INT,milestone_id INT,amount INT,status TEXT DEFAULT 'FUNDED',funded_at TIMESTAMPTZ DEFAULT now(),released_at TIMESTAMPTZ);
CREATE TABLE payouts(id SERIAL PRIMARY KEY,escrow_id INT,user_id INT,amount INT,reason TEXT,status TEXT DEFAULT 'PAID');
CREATE TABLE credentials(id SERIAL PRIMARY KEY,project_id INT,user_id INT,credential_type TEXT,issued_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE disputes(id SERIAL PRIMARY KEY,project_id INT,raised_by INT,reason TEXT,evidence TEXT,status TEXT DEFAULT 'OPEN',resolution TEXT);
CREATE TABLE ledger_entries(id SERIAL PRIMARY KEY,project_id INT,actor_id INT,actor_type TEXT,human_owner_id INT,action TEXT,details TEXT,ts TEXT,prev_hash TEXT,hash TEXT);
